'use client';
import { useState, useEffect } from 'react';
import { Calendar, Search, Filter, CheckCircle, XCircle, Clock } from 'lucide-react';

export default function BookingsManagement() {
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/bookings');
      if (res.ok) {
        const data = await res.json();
        setBookings(data);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const updateStatus = async (id, newStatus) => {
      // In real app, call API to update status
      // const res = await fetch(`.../api/bookings/${id}`, { method: 'PATCH', ... })
      
      // Optimistic update
      setBookings(prev => prev.map(b => b.id === id ? { ...b, status: newStatus } : b));
      alert(`Booking #${id} marked as ${newStatus}`);
  };

  const filteredBookings = bookings.filter(b => {
      const matchesSearch = b.patient_name?.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            b.service_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                            b.id.toString().includes(searchTerm);
      const matchesStatus = statusFilter === 'All' || b.status === statusFilter;
      return matchesSearch && matchesStatus;
  });

  return (
    <div>
        <h1 style={{ marginBottom: '2rem' }}>Bookings Management</h1>

        {/* Filters */}
        <div className="glass" style={{ padding: '1rem', display: 'flex', gap: '1rem', marginBottom: '2rem', alignItems: 'center', flexWrap: 'wrap' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flex: 1, minWidth: '200px' }}>
                <Search size={20} style={{ color: 'var(--text-muted)' }} />
                <input 
                    type="text" 
                    placeholder="Search by ID, Patient, or Service..." 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    style={{ background: 'transparent', border: 'none', color: '#fff', flex: 1, outline: 'none' }} 
                />
            </div>
            
            <div style={{ width: '1px', height: '20px', background: 'rgba(255,255,255,0.1)' }}></div>
            
            <div style={{ display: 'flex', gap: '0.5rem' }}>
                {['All', 'Confirmed', 'Completed', 'Cancelled'].map(status => (
                    <button 
                        key={status}
                        onClick={() => setStatusFilter(status)}
                        style={{
                            padding: '0.5rem 1rem',
                            borderRadius: '20px',
                            border: 'none',
                            background: statusFilter === status ? 'var(--primary)' : 'rgba(255,255,255,0.05)',
                            color: statusFilter === status ? '#000' : 'var(--text-muted)',
                            cursor: 'pointer',
                            fontSize: '0.9rem'
                        }}
                    >
                        {status}
                    </button>
                ))}
            </div>
        </div>

        {/* Table */}
        <div className="glass" style={{ padding: '0', overflow: 'hidden' }}>
            <div style={{ overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                    <thead>
                        <tr style={{ borderBottom: '1px solid rgba(255,255,255,0.1)', background: 'rgba(255,255,255,0.02)' }}>
                            <th style={{ padding: '1rem' }}>ID</th>
                            <th style={{ padding: '1rem' }}>Patient Details</th>
                            <th style={{ padding: '1rem' }}>Service Info</th>
                            <th style={{ padding: '1rem' }}>Schedule</th>
                            <th style={{ padding: '1rem' }}>Amount</th>
                            <th style={{ padding: '1rem' }}>Status</th>
                            <th style={{ padding: '1rem' }}>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filteredBookings.map((booking) => (
                            <tr key={booking.id} style={{ borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                                <td style={{ padding: '1rem', color: 'var(--text-muted)' }}>#{booking.id}</td>
                                <td style={{ padding: '1rem' }}>
                                    <div style={{ fontWeight: '500' }}>{booking.patient_name}</div>
                                    <div style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>{booking.user_phone}</div>
                                </td>
                                <td style={{ padding: '1rem' }}>{booking.service_name}</td>
                                <td style={{ padding: '1rem' }}>
                                    <div>{new Date(booking.booking_date).toLocaleDateString()}</div>
                                    <div style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>{booking.booking_time}</div>
                                </td>
                                <td style={{ padding: '1rem', fontWeight: 'bold' }}>₹{booking.price}</td>
                                <td style={{ padding: '1rem' }}>
                                    <span style={{ 
                                        padding: '4px 10px', 
                                        borderRadius: '20px', 
                                        fontSize: '0.8rem',
                                        background: booking.status === 'Completed' ? 'rgba(46, 204, 113, 0.2)' : 
                                                    booking.status === 'Cancelled' ? 'rgba(231, 76, 60, 0.2)' : 'rgba(0, 210, 211, 0.2)',
                                        color: booking.status === 'Completed' ? '#2ecc71' : 
                                               booking.status === 'Cancelled' ? '#e74c3c' : 'var(--primary)'
                                    }}>
                                        {booking.status}
                                    </span>
                                </td>
                                <td style={{ padding: '1rem' }}>
                                    <div style={{ display: 'flex', gap: '0.5rem' }}>
                                        <button onClick={() => updateStatus(booking.id, 'Completed')} title="Mark Complete" style={{ background: 'rgba(46, 204, 113, 0.1)', border: 'none', cursor: 'pointer', color: '#2ecc71', padding: '6px', borderRadius: '4px' }}><CheckCircle size={16} /></button>
                                        <button onClick={() => updateStatus(booking.id, 'Cancelled')} title="Cancel Booking" style={{ background: 'rgba(231, 76, 60, 0.1)', border: 'none', cursor: 'pointer', color: '#e74c3c', padding: '6px', borderRadius: '4px' }}><XCircle size={16} /></button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                {filteredBookings.length === 0 && !loading && (
                    <div style={{ padding: '3rem', textAlign: 'center', color: 'var(--text-muted)' }}>No bookings found.</div>
                )}
            </div>
        </div>
    </div>
  );
}
